module.exports = {"project_id":"kkzkuyhgdvyecmxtmkpy","name":"process-notification-queue","entrypoint_path":"functions/process-notification-queue/index.ts","verify_jwt":false,"files":[{"name":"functions/process-notification-queue/index.ts","content":"import { createClient } from \"https://esm.sh/@supabase/supabase-js@2.93.3\";\r\nimport { getCredential } from \"../_shared/credentials.ts\";\r\nimport { deliverWhatsAppForQueueItem } from \"../_shared/whatsapp-notify.ts\";\r\nimport { checkRateLimit } from \"../_shared/rate-limiter.ts\";\r\nimport {\r\n  isWithinQuietHours,\r\n  moveToDeadLetter,\r\n  pnqLog,\r\n  updateTokenHealth,\r\n} from \"../_shared/notification-ops.ts\";\r\n\r\nconst corsHeaders = {\r\n  \"Access-Control-Allow-Origin\": \"*\",\r\n  \"Access-Control-Allow-Headers\": \"authorization, x-client-info, apikey, content-type\",\r\n};\r\n\r\nconst MAX_TOTAL_ATTEMPTS = 9; // 3 retry cycles of 3 attempts each\r\nconst PUSH_TIMEOUT_MS = 5000;\r\nconst DEFAULT_PUSH_RATE_PER_HOUR = 60;\r\n\r\n// ─── APNs Direct Delivery ───\r\n\r\nfunction b64url(data: Uint8Array): string {\r\n  return btoa(String.fromCharCode(...data))\r\n    .replace(/\\+/g, \"-\")\r\n    .replace(/\\//g, \"_\")\r\n    .replace(/=+$/, \"\");\r\n}\r\n\r\nfunction b64urlStr(s: string): string {\r\n  return b64url(new TextEncoder().encode(s));\r\n}\r\n\r\nasync function importP8Key(pem: string): Promise<CryptoKey> {\r\n  const cleaned = pem\r\n    .replace(/-----BEGIN PRIVATE KEY-----/g, \"\")\r\n    .replace(/-----END PRIVATE KEY-----/g, \"\")\r\n    .replace(/\\\\n/g, \"\")\r\n    .replace(/\\s+/g, \"\");\r\n  const binaryDer = Uint8Array.from(atob(cleaned), (c) => c.charCodeAt(0));\r\n  return crypto.subtle.importKey(\r\n    \"pkcs8\",\r\n    binaryDer,\r\n    { name: \"ECDSA\", namedCurve: \"P-256\" },\r\n    false,\r\n    [\"sign\"]\r\n  );\r\n}\r\n\r\nasync function createApnsJwt(key: CryptoKey, keyId: string, teamId: string): Promise<string> {\r\n  const header = b64urlStr(JSON.stringify({ alg: \"ES256\", kid: keyId }));\r\n  const now = Math.floor(Date.now() / 1000);\r\n  const claims = b64urlStr(JSON.stringify({ iss: teamId, iat: now, exp: now + 3600 }));\r\n  const signingInput = `${header}.${claims}`;\r\n  const signature = await crypto.subtle.sign(\r\n    { name: \"ECDSA\", hash: \"SHA-256\" },\r\n    key,\r\n    new TextEncoder().encode(signingInput)\r\n  );\r\n  return `${signingInput}.${b64url(new Uint8Array(signature))}`;\r\n}\r\n\r\nasync function sendApnsDirect(\r\n  apnsToken: string, title: string, body: string,\r\n  data: Record<string, string> | undefined,\r\n  p8Key: string, keyId: string, teamId: string, bundleId: string,\r\n  threadId?: string, imageUrl?: string, highPriority = true,\r\n): Promise<{ success: boolean; error?: string }> {\r\n  try {\r\n    const cryptoKey = await importP8Key(p8Key);\r\n    const jwt = await createApnsJwt(cryptoKey, keyId, teamId);\r\n    const apnsSound = highPriority ? \"order_ring.mp3\" : \"default\";\r\n    const apnsPayload: Record<string, unknown> = {\r\n      aps: {\r\n        alert: { title, body },\r\n        sound: apnsSound,\r\n        badge: 1,\r\n        \"mutable-content\": imageUrl ? 1 : 0,\r\n        ...(threadId ? { \"thread-id\": threadId } : {}),\r\n      },\r\n      ...(data || {}),\r\n      ...(imageUrl ? { image_url: imageUrl } : {}),\r\n    };\r\n    const url = `https://api.push.apple.com/3/device/${apnsToken}`;\r\n    const apnsHeaders: Record<string, string> = {\r\n      Authorization: `bearer ${jwt}`,\r\n      \"apns-topic\": bundleId,\r\n      \"apns-push-type\": \"alert\",\r\n      \"apns-priority\": \"10\",\r\n      \"Content-Type\": \"application/json\",\r\n    };\r\n    if (threadId) apnsHeaders[\"apns-collapse-id\"] = threadId.substring(0, 64);\r\n\r\n    const resp = await fetch(url, { method: \"POST\", headers: apnsHeaders, body: JSON.stringify(apnsPayload) });\r\n    if (resp.status === 200) return { success: true };\r\n    if (resp.status === 410) return { success: false, error: \"INVALID_TOKEN\" };\r\n    const respBody = await resp.text().catch(() => \"\");\r\n    return { success: false, error: `APNs ${resp.status}: ${respBody}` };\r\n  } catch (err) {\r\n    return { success: false, error: String(err) };\r\n  }\r\n}\r\n\r\n// ─── FCM Direct Delivery ───\r\n\r\ninterface FirebaseServiceAccount {\r\n  client_email: string;\r\n  private_key: string;\r\n  token_uri: string;\r\n  project_id: string;\r\n}\r\n\r\nasync function generateFcmAccessToken(sa: FirebaseServiceAccount): Promise<string> {\r\n  const now = Math.floor(Date.now() / 1000);\r\n  const header = btoa(JSON.stringify({ alg: \"RS256\", typ: \"JWT\" })).replace(/=/g, \"\").replace(/\\+/g, \"-\").replace(/\\//g, \"_\");\r\n  const payload = btoa(JSON.stringify({\r\n    iss: sa.client_email, scope: \"https://www.googleapis.com/auth/cloud-platform\",\r\n    aud: sa.token_uri, iat: now, exp: now + 3600,\r\n  })).replace(/=/g, \"\").replace(/\\+/g, \"-\").replace(/\\//g, \"_\");\r\n  const unsigned = `${header}.${payload}`;\r\n  const pkPem = sa.private_key.replace(/\\\\n/g, \"\\n\");\r\n  const pkContents = pkPem.replace(\"-----BEGIN PRIVATE KEY-----\", \"\").replace(\"-----END PRIVATE KEY-----\", \"\").replace(/[\\n\\r\\s]/g, \"\");\r\n  const binaryKey = Uint8Array.from(atob(pkContents), (c) => c.charCodeAt(0));\r\n  const cryptoKey = await crypto.subtle.importKey(\"pkcs8\", binaryKey, { name: \"RSASSA-PKCS1-v1_5\", hash: \"SHA-256\" }, false, [\"sign\"]);\r\n  const sig = await crypto.subtle.sign(\"RSASSA-PKCS1-v1_5\", cryptoKey, new TextEncoder().encode(unsigned));\r\n  const sigB64 = btoa(String.fromCharCode(...new Uint8Array(sig))).replace(/=/g, \"\").replace(/\\+/g, \"-\").replace(/\\//g, \"_\");\r\n  const jwt = `${unsigned}.${sigB64}`;\r\n  const tokenResp = await fetch(sa.token_uri, {\r\n    method: \"POST\", headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\r\n    body: `grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=${jwt}`,\r\n  });\r\n  if (!tokenResp.ok) throw new Error(`FCM token error: ${await tokenResp.text()}`);\r\n  return (await tokenResp.json()).access_token;\r\n}\r\n\r\nasync function sendFcmDirect(\r\n  accessToken: string, projectId: string, deviceToken: string,\r\n  title: string, body: string, data?: Record<string, string>,\r\n  threadId?: string, imageUrl?: string, highPriority = true,\r\n): Promise<{ success: boolean; error?: string }> {\r\n  // New channel id required when sound changes (Android channel settings are immutable).\r\n  const androidSound = highPriority ? \"order_ring\" : \"default\";\r\n  const androidChannel = highPriority ? \"orders_incoming_v1\" : \"general\";\r\n  const androidNotif: Record<string, unknown> = { sound: androidSound, channel_id: androidChannel, icon: \"ic_stat_sociva\" };\r\n  if (threadId) androidNotif.tag = threadId;\r\n  if (imageUrl) androidNotif.image = imageUrl;\r\n  const fcmNotif: Record<string, unknown> = { title, body };\r\n  if (imageUrl) fcmNotif.image = imageUrl;\r\n  const fcmApnsSound = highPriority ? \"order_ring.mp3\" : \"default\";\r\n  const apnsAps: Record<string, unknown> = { alert: { title, body }, sound: fcmApnsSound, badge: 1 };\r\n  if (imageUrl) apnsAps[\"mutable-content\"] = 1;\r\n  if (threadId) apnsAps[\"thread-id\"] = threadId;\r\n  const apnsHeaders: Record<string, string> = { \"apns-push-type\": \"alert\", \"apns-priority\": \"10\" };\r\n  if (threadId) apnsHeaders[\"apns-collapse-id\"] = threadId.substring(0, 64);\r\n\r\n  const message = {\r\n    message: {\r\n      token: deviceToken, notification: fcmNotif, data: data || {},\r\n      android: { priority: \"high\", notification: androidNotif },\r\n      apns: { headers: apnsHeaders, payload: { aps: apnsAps, ...(imageUrl ? { image_url: imageUrl } : {}) } },\r\n    },\r\n  };\r\n\r\n  try {\r\n    const resp = await fetch(`https://fcm.googleapis.com/v1/projects/${projectId}/messages:send`, {\r\n      method: \"POST\",\r\n      headers: { Authorization: `Bearer ${accessToken}`, \"Content-Type\": \"application/json\" },\r\n      body: JSON.stringify(message),\r\n    });\r\n    const respText = await resp.text();\r\n    if (resp.ok) return { success: true };\r\n    let errorData: any;\r\n    try { errorData = JSON.parse(respText); } catch { errorData = { raw: respText }; }\r\n    if (errorData.error?.details?.some((d: any) => d.errorCode === \"UNREGISTERED\" || d.errorCode === \"INVALID_ARGUMENT\")) {\r\n      return { success: false, error: \"INVALID_TOKEN\" };\r\n    }\r\n    return { success: false, error: JSON.stringify(errorData) };\r\n  } catch (err) {\r\n    return { success: false, error: String(err) };\r\n  }\r\n}\r\n\r\n// ─── Timeout helper ───\r\nfunction withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {\r\n  return Promise.race([\r\n    promise,\r\n    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(`Timeout after ${ms}ms`)), ms)),\r\n  ]);\r\n}\r\n\r\n// ─── Inline Push Delivery ───\r\n\r\ninterface CachedCredentials {\r\n  fcmConfigured: boolean;\r\n  serviceAccount?: FirebaseServiceAccount;\r\n  fcmAccessToken?: string;\r\n  apnsConfigured: boolean;\r\n  apnsP8Key?: string;\r\n  apnsKeyId?: string;\r\n  apnsTeamId?: string;\r\n  apnsBundleId?: string;\r\n}\r\n\r\nfunction looksLikePlaceholder(s: string | undefined): boolean {\r\n  if (!s) return true;\r\n  const t = s.trim();\r\n  return t.length === 0 || /^PLACEHOLDER/i.test(t) || /your[_-]?(key|here|token)/i.test(t);\r\n}\r\n\r\nasync function loadCredentials(supabase: any): Promise<CachedCredentials> {\r\n  // ── FCM (Firebase) — optional ──\r\n  let fcmConfigured = false;\r\n  let serviceAccount: FirebaseServiceAccount | undefined;\r\n  let fcmAccessToken: string | undefined;\r\n  try {\r\n    const serviceAccountJson = await getCredential(supabase, \"firebase_service_account\", \"FIREBASE_SERVICE_ACCOUNT\");\r\n    if (serviceAccountJson && !looksLikePlaceholder(serviceAccountJson)) {\r\n      serviceAccount = JSON.parse(serviceAccountJson) as FirebaseServiceAccount;\r\n      fcmAccessToken = await generateFcmAccessToken(serviceAccount);\r\n      fcmConfigured = true;\r\n    } else {\r\n      console.warn(\"[PNQ] FIREBASE_SERVICE_ACCOUNT missing or placeholder — FCM disabled\");\r\n    }\r\n  } catch (e) {\r\n    console.warn(`[PNQ] FCM init failed (continuing without FCM): ${e}`);\r\n    serviceAccount = undefined;\r\n    fcmAccessToken = undefined;\r\n    fcmConfigured = false;\r\n  }\r\n\r\n  // ── APNs — optional; accept both APNS_AUTH_KEY and APNS_KEY_P8 ──\r\n  const [apnsP8KeyA, apnsP8KeyB, apnsKeyId, apnsTeamId, apnsBundleId] = await Promise.all([\r\n    getCredential(supabase, \"apns_auth_key\", \"APNS_AUTH_KEY\"),\r\n    getCredential(supabase, \"apns_key_p8\", \"APNS_KEY_P8\"),\r\n    getCredential(supabase, \"apns_key_id\", \"APNS_KEY_ID\"),\r\n    getCredential(supabase, \"apns_team_id\", \"APNS_TEAM_ID\"),\r\n    getCredential(supabase, \"apns_bundle_id\", \"APNS_BUNDLE_ID\"),\r\n  ]);\r\n  const apnsP8Key = (!looksLikePlaceholder(apnsP8KeyA) ? apnsP8KeyA : undefined)\r\n    ?? (!looksLikePlaceholder(apnsP8KeyB) ? apnsP8KeyB : undefined);\r\n  const apnsConfigured = !!(apnsP8Key\r\n    && !looksLikePlaceholder(apnsKeyId)\r\n    && !looksLikePlaceholder(apnsTeamId)\r\n    && !looksLikePlaceholder(apnsBundleId));\r\n\r\n  return {\r\n    fcmConfigured,\r\n    serviceAccount,\r\n    fcmAccessToken,\r\n    apnsConfigured,\r\n    apnsP8Key,\r\n    apnsKeyId,\r\n    apnsTeamId,\r\n    apnsBundleId,\r\n  };\r\n}\r\n\r\nasync function deliverPushToUser(\r\n  supabase: any, creds: CachedCredentials, userId: string,\r\n  title: string, body: string, pushData: Record<string, string>,\r\n  threadId?: string, imageUrl?: string, notificationId?: string,\r\n  highPriority = false,\r\n): Promise<{ successCount: number; failCount: number }> {\r\n  const startMs = Date.now();\r\n\r\n  // Fetch valid device tokens (prefer healthier / recently successful)\r\n  const { data: tokens, error: tokensErr } = await supabase\r\n    .from(\"device_tokens\")\r\n    .select(\"id, token, platform, apns_token, updated_at, invalid_count, health_score, consecutive_failures, last_success_at\")\r\n    .eq(\"user_id\", userId)\r\n    .eq(\"invalid\", false);\r\n\r\n  if (tokensErr || !tokens || tokens.length === 0) {\r\n    pnqLog(\"push_no_tokens\", { notification_id: notificationId, user_id: userId });\r\n    return { successCount: 0, failCount: 0 };\r\n  }\r\n\r\n  // Deduplicate: keep highest health per platform, then latest updated\r\n  const sorted = [...tokens].sort((a: any, b: any) => {\r\n    const hs = (b.health_score ?? 100) - (a.health_score ?? 100);\r\n    if (hs !== 0) return hs;\r\n    return new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime();\r\n  });\r\n  const seenPlatform = new Set<string>();\r\n  const deduped = sorted.filter((t: any) => {\r\n    if ((t.health_score ?? 100) < 10) return false;\r\n    if (seenPlatform.has(t.platform)) return false;\r\n    seenPlatform.add(t.platform);\r\n    return true;\r\n  });\r\n\r\n  let successCount = 0;\r\n  let failCount = 0;\r\n\r\n  for (const tokenRecord of deduped) {\r\n    const tokenStartMs = Date.now();\r\n    let result: { success: boolean; error?: string };\r\n    const isApnsOnlyToken = tokenRecord.token.startsWith(\"apns:\");\r\n\r\n    try {\r\n      // iOS with APNs token → direct APNs (primary), FCM fallback if available\r\n      if (tokenRecord.platform === \"ios\" && tokenRecord.apns_token && creds.apnsConfigured) {\r\n        result = await withTimeout(\r\n          sendApnsDirect(tokenRecord.apns_token, title, body, pushData, creds.apnsP8Key!, creds.apnsKeyId!, creds.apnsTeamId!, creds.apnsBundleId!, threadId, imageUrl, highPriority),\r\n          PUSH_TIMEOUT_MS,\r\n        );\r\n        // FCM fallback if APNs fails (non-invalid) and we have a real FCM token + FCM configured\r\n        if (!result.success && result.error !== \"INVALID_TOKEN\" && !isApnsOnlyToken && creds.fcmConfigured) {\r\n          console.log(`[Push] APNs failed for ${notificationId}, falling back to FCM`);\r\n          result = await withTimeout(\r\n            sendFcmDirect(creds.fcmAccessToken!, creds.serviceAccount!.project_id, tokenRecord.token, title, body, pushData, threadId, imageUrl, highPriority),\r\n            PUSH_TIMEOUT_MS,\r\n          );\r\n        }\r\n      } else if (isApnsOnlyToken) {\r\n        // APNs-only token but APNs not configured\r\n        result = { success: false, error: \"APNS_NOT_CONFIGURED\" };\r\n      } else if (creds.fcmConfigured) {\r\n        // Android or iOS without APNs → FCM\r\n        result = await withTimeout(\r\n          sendFcmDirect(creds.fcmAccessToken!, creds.serviceAccount!.project_id, tokenRecord.token, title, body, pushData, threadId, imageUrl, highPriority),\r\n          PUSH_TIMEOUT_MS,\r\n        );\r\n      } else {\r\n        result = { success: false, error: \"FCM_NOT_CONFIGURED\" };\r\n      }\r\n    } catch (err) {\r\n      result = { success: false, error: String(err) };\r\n    }\r\n\r\n    // Safe token handling: health score + prune on sustained / invalid failures\r\n    await updateTokenHealth(supabase, tokenRecord, result);\r\n\r\n    pnqLog(\"push_delivery\", {\r\n      notification_id: notificationId,\r\n      platform: tokenRecord.platform,\r\n      success: result.success,\r\n      duration_ms: Date.now() - tokenStartMs,\r\n      error: result.error || null,\r\n    });\r\n\r\n    if (result.success) successCount++;\r\n    else failCount++;\r\n  }\r\n\r\n  return { successCount, failCount };\r\n}\r\n\r\n// ─── Self-rescheduling (replaces pg_cron sweep) ───\r\n// `notification_queue` INSERT trigger fires the function in real-time.\r\n// This helper handles the two cases the cron used to cover:\r\n//   1. pending items with next_retry_at <= now  → re-invoke immediately\r\n//   2. pending items with next_retry_at in the future → delayed self-invoke\r\n// It uses EdgeRuntime.waitUntil so the response returns immediately while\r\n// the follow-up call is scheduled in the background.\r\nasync function scheduleNextRun(supabase: any, supabaseUrl: string): Promise<void> {\r\n  try {\r\n    const { data: dueRows } = await supabase\r\n      .from(\"notification_queue\")\r\n      .select(\"id\", { count: \"exact\", head: false })\r\n      .eq(\"status\", \"pending\")\r\n      .or(\"next_retry_at.is.null,next_retry_at.lte.\" + new Date().toISOString())\r\n      .limit(1);\r\n    const hasDueNow = !!(dueRows && dueRows.length > 0);\r\n\r\n    let delayMs = 0;\r\n    if (!hasDueNow) {\r\n      const { data: futureRows } = await supabase\r\n        .from(\"notification_queue\")\r\n        .select(\"next_retry_at\")\r\n        .eq(\"status\", \"pending\")\r\n        .not(\"next_retry_at\", \"is\", null)\r\n        .gt(\"next_retry_at\", new Date().toISOString())\r\n        .order(\"next_retry_at\", { ascending: true })\r\n        .limit(1);\r\n      if (!futureRows || futureRows.length === 0) {\r\n        return; // nothing to do\r\n      }\r\n      delayMs = Math.max(\r\n        500,\r\n        new Date(futureRows[0].next_retry_at).getTime() - Date.now(),\r\n      );\r\n      // Cap at 5 min so we never schedule something the runtime can't keep alive\r\n      if (delayMs > 5 * 60 * 1000) return;\r\n    }\r\n\r\n    const anonKey = Deno.env.get(\"SUPABASE_ANON_KEY\")!;\r\n    const selfUrl = `${supabaseUrl}/functions/v1/process-notification-queue`;\r\n    const invoke = () =>\r\n      fetch(selfUrl, {\r\n        method: \"POST\",\r\n        headers: {\r\n          \"Content-Type\": \"application/json\",\r\n          Authorization: `Bearer ${anonKey}`,\r\n        },\r\n        body: JSON.stringify({ trigger: \"self_reschedule\", time: new Date().toISOString() }),\r\n      }).catch((e) => console.warn(\"[PNQ] Self-invoke failed:\", e));\r\n\r\n    const runtime = (globalThis as any).EdgeRuntime;\r\n    if (delayMs === 0) {\r\n      if (runtime?.waitUntil) runtime.waitUntil(invoke());\r\n      else invoke();\r\n      console.log(\"[PNQ] Self-rescheduled: immediate (more items due)\");\r\n    } else {\r\n      const task = new Promise<void>((resolve) =>\r\n        setTimeout(() => invoke().finally(() => resolve()), delayMs),\r\n      );\r\n      if (runtime?.waitUntil) runtime.waitUntil(task);\r\n      console.log(`[PNQ] Self-rescheduled: in ${delayMs}ms (next retry)`);\r\n    }\r\n  } catch (e) {\r\n    console.warn(\"[PNQ] scheduleNextRun failed:\", e);\r\n  }\r\n}\r\n\r\n// ─── Main Handler ───\r\n\r\nDeno.serve(async (req) => {\r\n  console.log(`[PNQ] Invoked: method=${req.method}, url=${req.url}`);\r\n  if (req.method === \"OPTIONS\") {\r\n    return new Response(null, { headers: corsHeaders });\r\n  }\r\n\r\n  try {\r\n    const supabaseUrl = Deno.env.get(\"SUPABASE_URL\")!;\r\n    const supabaseServiceKey = Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\")!;\r\n\r\n    // Auth gate (audit P0): service_role, cron secret, or admin JWT — mirror process-wallet-expiry\r\n    const authHeader = req.headers.get(\"Authorization\") || \"\";\r\n    const isService = authHeader === `Bearer ${supabaseServiceKey}`;\r\n    const isCron = req.headers.get(\"x-cron-secret\") === Deno.env.get(\"CRON_SECRET\");\r\n    let isAdmin = false;\r\n    if (!isService && !isCron && authHeader.startsWith(\"Bearer \")) {\r\n      try {\r\n        const userClient = createClient(supabaseUrl, Deno.env.get(\"SUPABASE_ANON_KEY\")!, {\r\n          global: { headers: { Authorization: authHeader } },\r\n        });\r\n        const { data: { user } } = await userClient.auth.getUser();\r\n        if (user) {\r\n          const adminClient = createClient(supabaseUrl, supabaseServiceKey);\r\n          const { data: role } = await adminClient\r\n            .from(\"user_roles\")\r\n            .select(\"role\")\r\n            .eq(\"user_id\", user.id)\r\n            .eq(\"role\", \"admin\")\r\n            .maybeSingle();\r\n          isAdmin = !!role;\r\n        }\r\n      } catch (e) {\r\n        console.warn(\"[PNQ] admin auth check failed:\", e);\r\n      }\r\n    }\r\n    if (!isService && !isCron && !isAdmin) {\r\n      return new Response(JSON.stringify({ error: \"Unauthorized\" }), {\r\n        status: 401,\r\n        headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\r\n      });\r\n    }\r\n\r\n    const supabase = createClient(supabaseUrl, supabaseServiceKey);\r\n\r\n    // Recover stuck notifications — reset items stuck in 'processing' for > 3 min\r\n    try {\r\n      const { data: unstuck } = await supabase\r\n        .from(\"notification_queue\")\r\n        .update({ status: \"pending\" })\r\n        .eq(\"status\", \"processing\")\r\n        .lt(\"created_at\", new Date(Date.now() - 3 * 60 * 1000).toISOString())\r\n        .select(\"id\");\r\n      if (unstuck && unstuck.length > 0) {\r\n        console.log(`[PNQ] Recovered ${unstuck.length} stuck 'processing' notifications`);\r\n      }\r\n    } catch (e) {\r\n      console.warn(`[PNQ] Stuck recovery exception: ${e}`);\r\n    }\r\n\r\n    // ── ORPHAN RECOVERY: auto-deliver failed items older than 1 hour without in-app notification ──\r\n    try {\r\n      const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString();\r\n      const { data: orphans, error: orphanErr } = await supabase\r\n        .from(\"notification_queue\")\r\n        .select(\"id, user_id, title, body, type, reference_path, payload\")\r\n        .eq(\"status\", \"failed\")\r\n        .lt(\"processed_at\", oneHourAgo)\r\n        .limit(25);\r\n\r\n      if (orphans && orphans.length > 0) {\r\n        // Check which ones already have in-app notifications\r\n        const orphanIds = orphans.map((o: any) => o.id);\r\n        const { data: existingNotifs } = await supabase\r\n          .from(\"user_notifications\")\r\n          .select(\"queue_item_id\")\r\n          .in(\"queue_item_id\", orphanIds);\r\n        const deliveredSet = new Set((existingNotifs || []).map((n: any) => n.queue_item_id));\r\n\r\n        let recoveredCount = 0;\r\n        for (const orphan of orphans) {\r\n          if (deliveredSet.has(orphan.id)) {\r\n            // Already has in-app — just mark processed\r\n            await supabase.from(\"notification_queue\")\r\n              .update({ status: \"processed\", processed_at: new Date().toISOString(), last_error: \"Orphan recovery: already delivered\" })\r\n              .eq(\"id\", orphan.id);\r\n            recoveredCount++;\r\n            continue;\r\n          }\r\n          // Create in-app notification and mark processed (defense-in-depth: write both column pairs)\r\n          const { error: insertErr } = await supabase.from(\"user_notifications\").insert({\r\n            user_id: orphan.user_id, title: orphan.title, body: orphan.body,\r\n            type: orphan.type,\r\n            reference_path: orphan.reference_path, action_url: orphan.reference_path,\r\n            queue_item_id: orphan.id,\r\n            payload: orphan.payload || null, data: orphan.payload || null,\r\n          });\r\n          \r\n          if (!insertErr || insertErr.code === '23505') {\r\n            await supabase.from(\"notification_queue\")\r\n              .update({ status: \"processed\", processed_at: new Date().toISOString(), last_error: \"Orphan recovery: auto-delivered as in-app\" })\r\n              .eq(\"id\", orphan.id);\r\n            recoveredCount++;\r\n          }\r\n        }\r\n        console.log(`[PNQ] Orphan recovery complete: ${recoveredCount}/${orphans.length}`);\r\n      }\r\n    } catch (e) {\r\n      console.warn(`[PNQ] Orphan recovery exception: ${e}`);\r\n    }\r\n\r\n    // Atomically claim pending notifications\r\n    const { data: pending, error: fetchError } = await supabase\r\n      .rpc(\"claim_notification_queue\", { _batch_size: 50 });\r\n\r\n    if (fetchError) {\r\n      console.error(\"Error fetching queue:\", fetchError);\r\n      return new Response(JSON.stringify({ error: fetchError.message }), {\r\n        status: 500, headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\r\n      });\r\n    }\r\n\r\n    if (!pending || pending.length === 0) {\r\n      console.log(\"[PNQ] No pending items to process\");\r\n      await scheduleNextRun(supabase, supabaseUrl);\r\n      return new Response(JSON.stringify({ processed: 0, retried: 0, dead_lettered: 0 }), {\r\n        headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\r\n      });\r\n    }\r\n\r\n    console.log(`[PNQ] Processing ${pending.length} queued notifications`);\r\n\r\n    // ── CREDENTIAL CACHING: Load ONCE per batch ──\r\n    let creds: CachedCredentials | null = null;\r\n    let pushAvailable = false;\r\n    try {\r\n      creds = await loadCredentials(supabase);\r\n      pushAvailable = creds.fcmConfigured || creds.apnsConfigured;\r\n      console.log(`[PNQ] Credentials loaded: FCM ${creds.fcmConfigured ? \"✅\" : \"❌\"}, APNs ${creds.apnsConfigured ? \"✅\" : \"❌\"}`);\r\n      if (!pushAvailable) {\r\n        console.warn(`[PNQ] Neither FCM nor APNs configured — delivering ${pending.length} items as in-app only`);\r\n      }\r\n    } catch (credErr) {\r\n      console.error(`[PNQ] Unexpected credential load failure: ${credErr}`);\r\n      pushAvailable = false;\r\n      console.log(`[PNQ] Push unavailable — delivering ${pending.length} items as in-app only`);\r\n    }\r\n\r\n    // Batch-fetch notification preferences + profile phones for WhatsApp channel\r\n    const userIds = [...new Set(pending.map((item: any) => item.user_id))];\r\n    const { data: prefRows } = await supabase\r\n      .from(\"notification_preferences\")\r\n      .select(\"user_id, orders, chat, promotions, whatsapp, whatsapp_opted_in_at, quiet_hours_enabled, quiet_hours_start, quiet_hours_end, timezone\")\r\n      .in(\"user_id\", userIds);\r\n    const prefMap = new Map<string, Record<string, any>>();\r\n    for (const row of prefRows || []) {\r\n      prefMap.set(row.user_id, {\r\n        orders: row.orders,\r\n        chat: row.chat,\r\n        promotions: row.promotions,\r\n        whatsapp: row.whatsapp !== false,\r\n        whatsapp_opted_in_at: row.whatsapp_opted_in_at ?? null,\r\n        quiet_hours_enabled: !!row.quiet_hours_enabled,\r\n        quiet_hours_start: row.quiet_hours_start ?? 22,\r\n        quiet_hours_end: row.quiet_hours_end ?? 7,\r\n        timezone: row.timezone || \"Asia/Kolkata\",\r\n      });\r\n    }\r\n    const { data: profileRows } = await supabase\r\n      .from(\"profiles\")\r\n      .select(\"id, phone, name\")\r\n      .in(\"id\", userIds);\r\n    const profileMap = new Map<string, { phone: string | null; name: string | null }>();\r\n    for (const row of profileRows || []) {\r\n      profileMap.set(row.id, { phone: row.phone ?? null, name: row.name ?? null });\r\n    }\r\n\r\n    // Rate-limit config (defaults if table missing / empty)\r\n    let maxPerHour = DEFAULT_PUSH_RATE_PER_HOUR;\r\n    try {\r\n      const { data: cfg } = await supabase\r\n        .from(\"notification_config\")\r\n        .select(\"value\")\r\n        .eq(\"key\", \"push_rate_limit\")\r\n        .maybeSingle();\r\n      if (cfg?.value?.max_per_user_per_hour) {\r\n        maxPerHour = Number(cfg.value.max_per_user_per_hour) || DEFAULT_PUSH_RATE_PER_HOUR;\r\n      }\r\n    } catch { /* use default */ }\r\n\r\n    let processed = 0;\r\n    let deadLettered = 0;\r\n    let skippedPrefs = 0;\r\n    let skippedQuiet = 0;\r\n    let skippedRate = 0;\r\n    let retriedCount = 0;\r\n    const batchStarted = Date.now();\r\n    const oldestCreated = pending.reduce((min: number, it: any) => {\r\n      const t = new Date(it.created_at).getTime();\r\n      return Number.isFinite(t) ? Math.min(min, t) : min;\r\n    }, Date.now());\r\n    pnqLog(\"queue_lag\", {\r\n      batch_size: pending.length,\r\n      oldest_age_ms: Date.now() - oldestCreated,\r\n    });\r\n\r\n    for (const item of pending) {\r\n      try {\r\n        // Enforce user notification preferences\r\n        const userPrefs = prefMap.get(item.user_id);\r\n        const notifType = item.type || item.payload?.type || \"order\";\r\n        let prefAllowed = true;\r\n        if (userPrefs) {\r\n          const isOrderRelated = notifType === \"order\" || notifType === \"order_status\" || notifType === \"order_update\"\r\n            || notifType.startsWith(\"delivery_\") || notifType.startsWith(\"booking_\");\r\n          if (isOrderRelated && userPrefs.orders === false) prefAllowed = false;\r\n          if ((notifType === \"chat\" || notifType === \"chat_message\" || notifType === \"message\") && userPrefs.chat === false) {\r\n            prefAllowed = false;\r\n          }\r\n          if ((notifType === \"promotion\" || notifType === \"campaign\") && userPrefs.promotions === false) {\r\n            prefAllowed = false;\r\n          }\r\n        }\r\n        if (!prefAllowed) {\r\n          console.log(`[Queue][${item.id}] Skipped push — user opted out of '${notifType}'`);\r\n          await supabase.from(\"user_notifications\").insert({\r\n            user_id: item.user_id, title: item.title, body: item.body,\r\n            type: item.type,\r\n            reference_path: item.reference_path, action_url: item.reference_path,\r\n            queue_item_id: item.id,\r\n            payload: item.payload || null, data: item.payload || null,\r\n          });\r\n          await supabase.from(\"notification_queue\")\r\n            .update({\r\n              status: \"processed\", processed_at: new Date().toISOString(),\r\n              push_attempted: false, push_skip_reason: \"prefs_opt_out\",\r\n            }).eq(\"id\", item.id);\r\n          skippedPrefs++;\r\n          processed++;\r\n          continue;\r\n        }\r\n\r\n        const silentPush = item.payload?.silent_push === true;\r\n\r\n        // Dedup check — skip if same (user_id, type, reference_path) exists within last 60s\r\n        if (item.reference_path) {\r\n          const sixtySecsAgo = new Date(Date.now() - 60_000).toISOString();\r\n          const { data: existing } = await supabase\r\n            .from(\"user_notifications\")\r\n            .select(\"id\")\r\n            .eq(\"user_id\", item.user_id).eq(\"type\", item.type)\r\n            .eq(\"reference_path\", item.reference_path)\r\n            .gte(\"created_at\", sixtySecsAgo).limit(1);\r\n          if (existing && existing.length > 0) {\r\n            console.log(`[Queue][${item.id}] Duplicate skipped`);\r\n            await supabase.from(\"notification_queue\")\r\n              .update({\r\n                status: \"processed\", processed_at: new Date().toISOString(),\r\n                push_attempted: false, push_skip_reason: \"dedup\",\r\n              }).eq(\"id\", item.id);\r\n            processed++;\r\n            continue;\r\n          }\r\n        }\r\n\r\n        // Guards: staleness + terminal-state + state-mismatch\r\n        const isOrderNotif = ['order_status', 'order', 'order_update'].includes(item.type);\r\n        const payloadOrderId = item.payload?.orderId || item.payload?.order_id;\r\n        const payloadStatus = item.payload?.status || item.payload?.new_status;\r\n        if (isOrderNotif && payloadOrderId) {\r\n          const ageMs = Date.now() - new Date(item.created_at).getTime();\r\n          const isStale = ageMs > 5 * 60 * 1000;\r\n          const { data: orderCheck } = await supabase\r\n            .from(\"orders\").select(\"status\").eq(\"id\", payloadOrderId).single();\r\n          if (orderCheck) {\r\n            const terminalStatuses = ['delivered', 'completed', 'cancelled', 'no_show', 'rejected', 'returned', 'failed'];\r\n            const isTerminal = terminalStatuses.includes(orderCheck.status);\r\n            const isStateMismatch = payloadStatus && payloadStatus !== orderCheck.status;\r\n            const isNewOrderNotif = ['placed', 'enquired', 'requested'].includes(payloadStatus);\r\n            if (((isStale && isTerminal) || isStateMismatch) && !isNewOrderNotif) {\r\n              await supabase.from(\"user_notifications\").insert({\r\n                user_id: item.user_id, title: item.title, body: item.body,\r\n                type: item.type,\r\n                reference_path: item.reference_path, action_url: item.reference_path,\r\n                queue_item_id: item.id,\r\n                payload: item.payload, data: item.payload,\r\n                is_read: true,\r\n              });\r\n              await supabase.from(\"notification_queue\")\r\n                .update({\r\n                  status: \"processed\", processed_at: new Date().toISOString(),\r\n                  push_attempted: false, push_skip_reason: \"stale_or_terminal\",\r\n                }).eq(\"id\", item.id);\r\n              processed++;\r\n              console.log(`[Queue][${item.id}] Skipped push: stale/terminal/mismatch`);\r\n              continue;\r\n            }\r\n          }\r\n        }\r\n\r\n        // Insert in-app notification (with dedup via queue_item_id) — write both column pairs\r\n        const { error: insertError } = await supabase.from(\"user_notifications\").insert({\r\n          user_id: item.user_id, title: item.title, body: item.body,\r\n          type: item.type,\r\n          reference_path: item.reference_path, action_url: item.reference_path,\r\n          queue_item_id: item.id,\r\n          payload: item.payload || null, data: item.payload || null,\r\n        });\r\n        if (insertError && insertError.code !== '23505') {\r\n          throw new Error(`DB insert failed: ${insertError.message}`);\r\n        }\r\n\r\n        // ── WhatsApp channel (best-effort; never blocks push/in-app) ──\r\n        try {\r\n          const profile = profileMap.get(item.user_id);\r\n          const wa = await deliverWhatsAppForQueueItem({\r\n            userId: item.user_id,\r\n            phone: profile?.phone,\r\n            userName: profile?.name,\r\n            type: item.type,\r\n            title: item.title,\r\n            body: item.body,\r\n            payload: item.payload || {},\r\n            whatsappPref: userPrefs?.whatsapp !== false,\r\n            whatsappOptedInAt: userPrefs?.whatsapp_opted_in_at ?? null,\r\n            promotionsPref: userPrefs?.promotions === true,\r\n            notificationId: item.id,\r\n          });\r\n          if (wa.attempted) {\r\n            pnqLog(\"whatsapp_delivery\", {\r\n              notification_id: item.id,\r\n              success: !!wa.result?.success,\r\n              code: wa.result?.code || null,\r\n              used_template: wa.result?.usedTemplate ?? null,\r\n              error: wa.result?.error || null,\r\n            });\r\n          } else if (wa.skipReason) {\r\n            pnqLog(\"whatsapp_skip\", { notification_id: item.id, reason: wa.skipReason });\r\n          }\r\n        } catch (waErr) {\r\n          console.warn(`[Queue][${item.id}] WhatsApp channel error:`, waErr);\r\n        }\r\n\r\n        // Silent push: skip device delivery\r\n        if (silentPush) {\r\n          console.log(`[Queue][${item.id}] Silent push — skipping device delivery`);\r\n          await supabase.from(\"notification_queue\")\r\n            .update({\r\n              status: \"processed\", processed_at: new Date().toISOString(),\r\n              push_attempted: false, push_skip_reason: \"silent\",\r\n            }).eq(\"id\", item.id);\r\n          processed++;\r\n          continue;\r\n        }\r\n\r\n        // If push provider is not available, mark as processed (in-app already delivered above)\r\n        if (!pushAvailable || !creds) {\r\n          await supabase.from(\"notification_queue\")\r\n            .update({\r\n              status: \"processed\", processed_at: new Date().toISOString(),\r\n              push_attempted: false, push_skip_reason: \"no_credentials\",\r\n              last_error: \"Push skipped — no push provider configured\",\r\n            }).eq(\"id\", item.id);\r\n          pnqLog(\"push_skip\", { notification_id: item.id, reason: \"no_credentials\" });\r\n          processed++;\r\n          continue;\r\n        }\r\n\r\n        // ── PRIORITY DETECTION ──\r\n        const rawPayload = item.payload || {};\r\n        const targetRole = rawPayload.target_role || '';\r\n        const notifStatus = rawPayload.status || '';\r\n\r\n        const SELLER_HIGH_PRIORITY_STATUSES = ['placed', 'enquired', 'requested', 'quoted'];\r\n        const BUYER_HIGH_PRIORITY_STATUSES = ['payment_failed', 'refund_failed', 'otp'];\r\n\r\n        const isHighPriority =\r\n          (targetRole === 'seller' && SELLER_HIGH_PRIORITY_STATUSES.includes(notifStatus)) ||\r\n          (targetRole === 'buyer' && BUYER_HIGH_PRIORITY_STATUSES.includes(notifStatus));\r\n\r\n        // Quiet hours: suppress non-urgent push (inbox + WA already handled)\r\n        if (\r\n          userPrefs &&\r\n          !isHighPriority &&\r\n          isWithinQuietHours({\r\n            enabled: userPrefs.quiet_hours_enabled,\r\n            startHour: userPrefs.quiet_hours_start,\r\n            endHour: userPrefs.quiet_hours_end,\r\n            timezone: userPrefs.timezone,\r\n          })\r\n        ) {\r\n          await supabase.from(\"notification_queue\")\r\n            .update({\r\n              status: \"processed\", processed_at: new Date().toISOString(),\r\n              push_attempted: false, push_skip_reason: \"quiet_hours\",\r\n            }).eq(\"id\", item.id);\r\n          pnqLog(\"push_skip\", { notification_id: item.id, reason: \"quiet_hours\", user_id: item.user_id });\r\n          skippedQuiet++;\r\n          processed++;\r\n          continue;\r\n        }\r\n\r\n        // Per-user push rate limit (high-priority still counts but is allowed through if over — soft)\r\n        const rateKey = `notif_push:${item.user_id}`;\r\n        const rate = await checkRateLimit(rateKey, maxPerHour, 3600);\r\n        if (!rate.allowed && !isHighPriority) {\r\n          await supabase.from(\"notification_queue\")\r\n            .update({\r\n              status: \"processed\", processed_at: new Date().toISOString(),\r\n              push_attempted: false, push_skip_reason: \"rate_limited\",\r\n            }).eq(\"id\", item.id);\r\n          pnqLog(\"push_skip\", { notification_id: item.id, reason: \"rate_limited\", user_id: item.user_id });\r\n          skippedRate++;\r\n          processed++;\r\n          continue;\r\n        }\r\n\r\n        pnqLog(\"push_priority\", {\r\n          notification_id: item.id,\r\n          user_id: item.user_id,\r\n          target_role: targetRole || 'unknown',\r\n          status: notifStatus || 'unknown',\r\n          isHighPriority,\r\n          sound: isHighPriority ? 'order_ring' : 'default',\r\n        });\r\n\r\n        // ── INLINE PUSH DELIVERY (no function-to-function call) ──\r\n        const TERMINAL_PUSH_STATUSES = [\r\n          'cancelled', 'completed', 'delivered', 'rejected', 'no_show',\r\n          'returned', 'failed', 'expired',\r\n        ];\r\n        const resolvedOrderId = payloadOrderId\r\n          || rawPayload.orderId\r\n          || rawPayload.order_id\r\n          || rawPayload.entity_id\r\n          || null;\r\n        const pushData: Record<string, string> = {};\r\n        if (rawPayload.action) pushData.action = String(rawPayload.action);\r\n        if (rawPayload.reference_path) pushData.reference_path = String(rawPayload.reference_path);\r\n        else if (item.reference_path) pushData.reference_path = item.reference_path;\r\n        if (rawPayload.action_url) pushData.action_url = String(rawPayload.action_url);\r\n        else if (pushData.reference_path) pushData.action_url = pushData.reference_path;\r\n        else if (item.reference_path) pushData.action_url = item.reference_path;\r\n        if (!pushData.route && (pushData.action_url || item.reference_path)) {\r\n          pushData.route = pushData.action_url || item.reference_path;\r\n        }\r\n        // Pass priority info to client for foreground sound decision\r\n        pushData.high_priority = isHighPriority ? 'true' : 'false';\r\n        if (targetRole) pushData.target_role = targetRole;\r\n        if (notifStatus) pushData.status = notifStatus;\r\n        // Client sync metadata — required for order-terminal-push / overlay dismiss\r\n        if (resolvedOrderId) {\r\n          const oid = String(resolvedOrderId);\r\n          pushData.order_id = oid;\r\n          pushData.orderId = oid;\r\n          pushData.entity_id = oid;\r\n          pushData.entity_type = 'order';\r\n        }\r\n        if (notifStatus) {\r\n          pushData.is_terminal = TERMINAL_PUSH_STATUSES.includes(String(notifStatus)) ? 'true' : 'false';\r\n        }\r\n        if (item.type) pushData.type = String(item.type);\r\n        if (item.id) pushData.queue_item_id = String(item.id);\r\n        if (rawPayload.notif_id) pushData.notif_id = String(rawPayload.notif_id);\r\n\r\n        const threadId = resolvedOrderId\r\n          ? String(resolvedOrderId)\r\n          : (rawPayload.orderId ? String(rawPayload.orderId) : undefined);\r\n        const imageUrl = rawPayload.image_url ? String(rawPayload.image_url) : undefined;\r\n\r\n        const { successCount, failCount } = await deliverPushToUser(\r\n          supabase, creds, item.user_id,\r\n          item.title, item.body, pushData,\r\n          threadId, imageUrl, item.id, isHighPriority,\r\n        );\r\n\r\n        if (successCount > 0 || failCount === 0) {\r\n          // At least one token succeeded OR no tokens exist — mark processed\r\n          const skipReason = (successCount === 0 && failCount === 0) ? \"no_tokens\" : null;\r\n          if (skipReason) pnqLog(\"push_skip\", { notification_id: item.id, reason: skipReason });\r\n          await supabase.from(\"notification_queue\")\r\n            .update({\r\n              status: \"processed\", processed_at: new Date().toISOString(),\r\n              push_attempted: true,\r\n              push_success_count: successCount,\r\n              push_fail_count: failCount,\r\n              push_skip_reason: skipReason,\r\n            }).eq(\"id\", item.id);\r\n          // Audit: mark delivered when at least one token succeeded\r\n          if (successCount > 0) {\r\n            await supabase.rpc(\"fn_mark_notification_delivered\", { _queue_id: item.id }).catch(() => {});\r\n          }\r\n          processed++;\r\n        } else {\r\n          // All tokens failed — re-queue with 15s delay\r\n          const retryCount = (item.retry_count || 0) + 1;\r\n          if (retryCount >= MAX_TOTAL_ATTEMPTS) {\r\n            const lastError = \"All push delivery attempts exhausted\";\r\n            await supabase.from(\"notification_queue\").update({\r\n              status: \"failed\", processed_at: new Date().toISOString(),\r\n              retry_count: retryCount, last_error: lastError,\r\n              push_attempted: true,\r\n              push_success_count: successCount,\r\n              push_fail_count: failCount,\r\n            }).eq(\"id\", item.id);\r\n            await moveToDeadLetter(supabase, {\r\n              id: item.id,\r\n              user_id: item.user_id,\r\n              type: item.type,\r\n              title: item.title,\r\n              body: item.body,\r\n              reference_path: item.reference_path,\r\n              payload: item.payload,\r\n              retry_count: retryCount,\r\n              last_error: lastError,\r\n            });\r\n            deadLettered++;\r\n            console.error(`[Queue][${item.id}] Dead-lettered after ${retryCount} attempts`);\r\n          } else {\r\n            const nextRetryAt = new Date(Date.now() + 15_000).toISOString();\r\n            await supabase.from(\"notification_queue\").update({\r\n              status: \"pending\", retry_count: retryCount,\r\n              last_error: \"Push delivery failed, re-queued\",\r\n              next_retry_at: nextRetryAt,\r\n              push_attempted: true,\r\n              push_success_count: successCount,\r\n              push_fail_count: failCount,\r\n            }).eq(\"id\", item.id);\r\n            retriedCount++;\r\n            console.warn(`[Queue][${item.id}] Re-queued (attempt ${retryCount}) at ${nextRetryAt}`);\r\n          }\r\n        }\r\n      } catch (err: any) {\r\n        const errorMsg = err?.message || String(err);\r\n        await supabase.from(\"notification_queue\").update({\r\n          status: \"failed\", processed_at: new Date().toISOString(), last_error: errorMsg,\r\n        }).eq(\"id\", item.id);\r\n        await moveToDeadLetter(supabase, {\r\n          id: item.id,\r\n          user_id: item.user_id,\r\n          type: item.type,\r\n          title: item.title,\r\n          body: item.body,\r\n          reference_path: item.reference_path,\r\n          payload: item.payload,\r\n          retry_count: item.retry_count,\r\n          last_error: errorMsg,\r\n        });\r\n        deadLettered++;\r\n        console.error(`[Queue][${item.id}] Fatal error: ${errorMsg}`);\r\n      }\r\n    }\r\n\r\n    pnqLog(\"batch_summary\", {\r\n      total: pending.length,\r\n      processed,\r\n      dead_lettered: deadLettered,\r\n      retried: retriedCount,\r\n      skipped_prefs: skippedPrefs,\r\n      skipped_quiet: skippedQuiet,\r\n      skipped_rate: skippedRate,\r\n      duration_ms: Date.now() - batchStarted,\r\n      oldest_age_ms: Date.now() - oldestCreated,\r\n    });\r\n\r\n    // Self-reschedule: replaces the cron sweep. If more items are due now,\r\n    // re-invoke immediately; if items are scheduled for the future, queue\r\n    // a delayed self-invoke so retries fire without pg_cron.\r\n    await scheduleNextRun(supabase, supabaseUrl);\r\n\r\n    return new Response(\r\n      JSON.stringify({\r\n        processed,\r\n        dead_lettered: deadLettered,\r\n        retried: retriedCount,\r\n        skipped_prefs: skippedPrefs,\r\n        skipped_quiet: skippedQuiet,\r\n        skipped_rate: skippedRate,\r\n        total: pending.length,\r\n      }),\r\n      { headers: { ...corsHeaders, \"Content-Type\": \"application/json\" } }\r\n    );\r\n  } catch (error) {\r\n    console.error(\"Error in process-notification-queue:\", error);\r\n    return new Response(JSON.stringify({ error: String(error) }), {\r\n      status: 500, headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\r\n    });\r\n  }\r\n});\r\n"},{"name":"functions/_shared/credentials.ts","content":"import { createClient } from \"https://esm.sh/@supabase/supabase-js@2.93.3\";\n\n/**\n * Read a credential from admin_settings table first, fall back to Deno env secret.\n * This ensures credentials saved via the Admin Panel take precedence.\n */\nexport async function getCredential(\n  supabase: any,\n  dbKey: string,\n  envKey: string\n): Promise<string | undefined> {\n  try {\n    const { data } = await supabase\n      .from(\"admin_settings\")\n      .select(\"value, is_active\")\n      .eq(\"key\", dbKey)\n      .maybeSingle();\n    if (data?.value && data.is_active !== false) return data.value;\n  } catch (e) {\n    console.warn(`DB credential lookup failed for ${dbKey}:`, e);\n  }\n  return Deno.env.get(envKey);\n}\n\n/** Create a service-role Supabase client for credential lookups */\nexport function createAdminClient() {\n  return createClient(\n    Deno.env.get(\"SUPABASE_URL\")!,\n    Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\")!\n  );\n}\n"},{"name":"functions/_shared/whatsapp-notify.ts","content":"/**\r\n * Maps notification_queue items → WhatsApp Cloud API sends.\r\n * Called from process-notification-queue as an additional channel (never replaces push/in-app).\r\n *\r\n * Until sociva_* templates are APPROVED, free-form fallback only delivers inside Meta's\r\n * ~24h customer service window (after the user messages the business). In-app opt-in CTA\r\n * (wa.me Hi) is user-initiated and does not require a \"register me\" template.\r\n */\r\nimport {\r\n  logWhatsAppMessage,\r\n  normalizeWhatsAppPhone,\r\n  sendWhatsAppTemplateOrText,\r\n  type WhatsAppSendResult,\r\n} from \"./whatsapp.ts\";\r\n\r\nconst WA_ELIGIBLE_TYPES = new Set([\r\n  \"order\",\r\n  \"order_status\",\r\n  \"order_update\",\r\n  \"booking_reminder_1_hour\",\r\n  \"booking_reminder_30_min\",\r\n  \"booking_reminder_10_min\",\r\n  \"delivery\",\r\n  \"delivery_en_route\",\r\n  \"delivery_stalled\",\r\n  \"settlement\",\r\n  \"review\",\r\n  \"review_received\",\r\n  \"review_nudge\",\r\n  \"low_rating_alert\",\r\n  \"seller_daily_summary\",\r\n  \"seller_approved\",\r\n  \"seller_rejected\",\r\n  \"seller_suspended\",\r\n  \"license_approved\",\r\n  \"license_rejected\",\r\n  \"product_approved\",\r\n  \"product_rejected\",\r\n]);\r\n\r\n/** Society/chat noise — never WhatsApp. Marketing is gated separately. */\r\nconst SKIP_TYPES = new Set([\r\n  \"chat\",\r\n  \"chat_message\",\r\n  \"visitor\",\r\n  \"parcel\",\r\n  \"dispute\",\r\n  \"snag\",\r\n  \"milestone\",\r\n  \"worker_job\",\r\n  \"moderation\",\r\n]);\r\n\r\nconst MARKETING_TYPES = new Set([\"promotion\", \"campaign\"]);\r\n\r\n/** Normalize mixed enqueue payload shapes (orderId vs order_id, status vs new_status). */\r\nexport function normalizeWaPayload(payload: Record<string, unknown> | null | undefined): Record<string, unknown> {\r\n  const p = { ...(payload || {}) };\r\n  if (!p.status && p.new_status) p.status = p.new_status;\r\n  if (!p.orderId && p.order_id) p.orderId = p.order_id;\r\n  if (!p.order_id && p.orderId) p.order_id = p.orderId;\r\n  if (!p.sellerName && p.seller_name) p.sellerName = p.seller_name;\r\n  if (!p.providerName && (p.sellerName || p.provider_name)) {\r\n    p.providerName = p.sellerName || p.provider_name;\r\n  }\r\n  return p;\r\n}\r\n\r\nfunction toWaPhone(raw: string | null | undefined): string | null {\r\n  if (!raw) return null;\r\n  const digits = String(raw).replace(/\\D/g, \"\");\r\n  if (digits.length === 10) return normalizeWhatsAppPhone(`91${digits}`);\r\n  return normalizeWhatsAppPhone(digits);\r\n}\r\n\r\nfunction shortOrderRef(payload: Record<string, unknown>, title: string): string {\r\n  const id = String(payload.orderId || payload.order_id || \"\").slice(0, 8);\r\n  if (id) return id.toUpperCase();\r\n  return title.slice(0, 24) || \"order\";\r\n}\r\n\r\nfunction statusHeadline(status: string): string {\r\n  const map: Record<string, string> = {\r\n    assigned: \"Provider assigned\",\r\n    provider_changed: \"Provider updated\",\r\n    on_the_way: \"On the way\",\r\n    arrived: \"Provider arrived\",\r\n    at_gate: \"At your gate\",\r\n    in_progress: \"Service started\",\r\n    picked_up: \"Order picked up\",\r\n    ready: \"Order ready\",\r\n    delivered: \"Delivered\",\r\n    completed: \"Completed\",\r\n    confirmed: \"Booking confirmed\",\r\n    scheduled: \"Booking scheduled\",\r\n    rescheduled: \"Rescheduled\",\r\n    cancelled: \"Cancelled\",\r\n    no_show: \"No-show\",\r\n    quoted: \"Quote received\",\r\n    accepted: \"Accepted\",\r\n    preparing: \"Preparing\",\r\n    settlement_eligible: \"Settlement eligible\",\r\n    settlement_paid: \"Settlement paid\",\r\n    released: \"Payment released\",\r\n  };\r\n  return map[status] || status.replace(/_/g, \" \") || \"Update\";\r\n}\r\n\r\nexport function shouldSendWhatsApp(opts: {\r\n  type: string;\r\n  whatsappPref?: boolean | null;\r\n  whatsappOptedInAt?: string | null;\r\n  promotionsPref?: boolean | null;\r\n  payload?: Record<string, unknown> | null;\r\n}): boolean {\r\n  // Hard Meta opt-in: require explicit whatsapp_opted_in_at (grandfathered in migration).\r\n  if (!opts.whatsappOptedInAt) return false;\r\n  if (opts.whatsappPref === false) return false;\r\n  if (opts.payload?.skip_whatsapp === true) return false;\r\n  if (SKIP_TYPES.has(opts.type)) return false;\r\n\r\n  // Marketing: require promotions + whatsapp prefs AND explicit enqueue flag\r\n  if (MARKETING_TYPES.has(opts.type) || opts.payload?.allow_whatsapp_marketing === true) {\r\n    return (\r\n      opts.promotionsPref === true &&\r\n      opts.whatsappPref !== false &&\r\n      !!opts.whatsappOptedInAt &&\r\n      opts.payload?.allow_whatsapp_marketing === true\r\n    );\r\n  }\r\n\r\n  if (opts.payload?.wa_template) return true;\r\n  if (WA_ELIGIBLE_TYPES.has(opts.type)) return true;\r\n  if (opts.type.startsWith(\"booking_\") || opts.type.startsWith(\"delivery_\")) return true;\r\n  if (opts.type.startsWith(\"seller_\") || opts.type.startsWith(\"license_\") || opts.type.startsWith(\"product_\")) {\r\n    return true;\r\n  }\r\n  if (opts.type.startsWith(\"review\") || opts.type.startsWith(\"settlement\")) return true;\r\n  return false;\r\n}\r\n\r\nfunction resolveTemplate(opts: {\r\n  type: string;\r\n  title: string;\r\n  body: string;\r\n  payload: Record<string, unknown>;\r\n  userName: string;\r\n}): { templateName: string; bodyParams: string[]; fallbackText: string } {\r\n  const payload = normalizeWaPayload(opts.payload);\r\n  const status = String(payload.status || \"\").toLowerCase();\r\n  const targetRole = String(payload.target_role || \"\");\r\n  const name = opts.userName || \"there\";\r\n  const orderRef = shortOrderRef(payload, opts.title);\r\n  const fallbackText = `${opts.title}\\n${opts.body}\\n— Sociva`;\r\n\r\n  if (payload.wa_template) {\r\n    const tpl = String(payload.wa_template);\r\n    if (tpl === \"sociva_booking_confirmed\") {\r\n      return {\r\n        templateName: tpl,\r\n        bodyParams: [\r\n          name,\r\n          String(payload.providerName || payload.sellerName || \"your provider\"),\r\n          orderRef,\r\n          String(payload.serviceDate || payload.date || \"—\"),\r\n          String(payload.serviceTime || payload.time || \"—\"),\r\n        ],\r\n        fallbackText,\r\n      };\r\n    }\r\n    if (tpl === \"sociva_booking_cancelled\") {\r\n      return {\r\n        templateName: tpl,\r\n        bodyParams: [\r\n          name,\r\n          orderRef,\r\n          String(payload.providerName || \"your provider\"),\r\n          String(payload.reason || opts.body || \"Cancelled\").slice(0, 200),\r\n        ],\r\n        fallbackText,\r\n      };\r\n    }\r\n    if (tpl === \"sociva_booking_reminder\") {\r\n      return {\r\n        templateName: tpl,\r\n        bodyParams: [\r\n          name,\r\n          String(payload.providerName || \"your provider\"),\r\n          String(payload.serviceDate || \"—\"),\r\n          String(payload.serviceTime || \"—\"),\r\n          orderRef,\r\n        ],\r\n        fallbackText,\r\n      };\r\n    }\r\n    if (tpl === \"sociva_new_order_seller\") {\r\n      return {\r\n        templateName: tpl,\r\n        bodyParams: [\r\n          String(payload.status || \"order\"),\r\n          `${orderRef} — ${opts.body}`.slice(0, 200),\r\n        ],\r\n        fallbackText,\r\n      };\r\n    }\r\n    if (\r\n      tpl === \"sociva_refund_update\" ||\r\n      tpl === \"sociva_payment_update\" ||\r\n      tpl === \"sociva_order_update\" ||\r\n      tpl === \"sociva_store_status\"\r\n    ) {\r\n      return {\r\n        templateName: tpl,\r\n        bodyParams: [name, orderRef || opts.type, (opts.title || statusHeadline(status) || \"Update\").slice(0, 120)],\r\n        fallbackText,\r\n      };\r\n    }\r\n  }\r\n\r\n  // Marketing (opt-in already gated in shouldSendWhatsApp)\r\n  if (MARKETING_TYPES.has(opts.type) || payload.allow_whatsapp_marketing === true) {\r\n    return {\r\n      templateName: \"sociva_order_update\",\r\n      bodyParams: [name, \"offer\", (opts.title || \"Sociva offer\").slice(0, 120)],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  // Seller new order / enquiry\r\n  if (\r\n    targetRole === \"seller\" &&\r\n    [\"placed\", \"enquired\", \"requested\", \"auto_accepted\"].includes(status)\r\n  ) {\r\n    return {\r\n      templateName: \"sociva_new_order_seller\",\r\n      bodyParams: [status || \"order\", `${orderRef} — ${opts.body}`.slice(0, 200)],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  // Booking / order lifecycle for buyers\r\n  if ([\"accepted\", \"auto_accepted\", \"confirmed\", \"scheduled\", \"preparing\"].includes(status)) {\r\n    return {\r\n      templateName: \"sociva_booking_confirmed\",\r\n      bodyParams: [\r\n        name,\r\n        String(payload.providerName || payload.sellerName || \"your provider\"),\r\n        orderRef,\r\n        String(payload.serviceDate || payload.date || \"soon\"),\r\n        String(payload.serviceTime || payload.time || \"—\"),\r\n      ],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  if (status === \"cancelled\" || status === \"no_show\") {\r\n    return {\r\n      templateName: \"sociva_booking_cancelled\",\r\n      bodyParams: [\r\n        name,\r\n        orderRef,\r\n        String(payload.providerName || \"your provider\"),\r\n        String(payload.reason || opts.body || status).slice(0, 200),\r\n      ],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  if (opts.type.startsWith(\"booking_reminder\")) {\r\n    return {\r\n      templateName: \"sociva_booking_reminder\",\r\n      bodyParams: [\r\n        name,\r\n        String(payload.providerName || \"your provider\"),\r\n        String(payload.serviceDate || \"today\"),\r\n        String(payload.serviceTime || \"soon\"),\r\n        orderRef,\r\n      ],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  // Provider / fulfillment lifecycle → utility order update\r\n  if (\r\n    [\r\n      \"assigned\",\r\n      \"provider_changed\",\r\n      \"on_the_way\",\r\n      \"arrived\",\r\n      \"at_gate\",\r\n      \"in_progress\",\r\n      \"picked_up\",\r\n      \"ready\",\r\n      \"delivered\",\r\n      \"completed\",\r\n      \"rescheduled\",\r\n      \"quoted\",\r\n    ].includes(status)\r\n  ) {\r\n    return {\r\n      templateName: \"sociva_order_update\",\r\n      bodyParams: [name, orderRef, statusHeadline(status).slice(0, 120)],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  if (\r\n    status.startsWith(\"refund\") ||\r\n    opts.title.toLowerCase().includes(\"refund\") ||\r\n    opts.type.includes(\"refund\")\r\n  ) {\r\n    return {\r\n      templateName: \"sociva_refund_update\",\r\n      bodyParams: [name, orderRef, (opts.title || \"Refund update\").slice(0, 120)],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  // Settlements / earnings digest\r\n  if (\r\n    opts.type === \"settlement\" ||\r\n    opts.type === \"seller_daily_summary\" ||\r\n    status.startsWith(\"settlement\") ||\r\n    status === \"released\" ||\r\n    status === \"eligible\" ||\r\n    status === \"settled\"\r\n  ) {\r\n    return {\r\n      templateName: \"sociva_payment_update\",\r\n      bodyParams: [name, orderRef || \"payout\", (opts.title || statusHeadline(status) || \"Earnings update\").slice(0, 120)],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  // Reviews\r\n  if (\r\n    opts.type === \"review_nudge\" ||\r\n    opts.type === \"review\" ||\r\n    opts.type === \"review_received\" ||\r\n    opts.type === \"low_rating_alert\"\r\n  ) {\r\n    return {\r\n      templateName: \"sociva_order_update\",\r\n      bodyParams: [name, orderRef || \"review\", (opts.title || \"Review update\").slice(0, 120)],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  if (\r\n    opts.type.startsWith(\"seller_\") ||\r\n    opts.type.startsWith(\"license_\") ||\r\n    opts.type.startsWith(\"product_\")\r\n  ) {\r\n    return {\r\n      templateName: \"sociva_store_status\",\r\n      bodyParams: [name, orderRef || opts.type, (opts.title || \"Account update\").slice(0, 120)],\r\n      fallbackText,\r\n    };\r\n  }\r\n\r\n  // Default utility order update\r\n  return {\r\n    templateName: \"sociva_order_update\",\r\n    bodyParams: [name, orderRef, (opts.title || statusHeadline(status) || \"Update\").slice(0, 120)],\r\n    fallbackText,\r\n  };\r\n}\r\n\r\nexport async function deliverWhatsAppForQueueItem(opts: {\r\n  userId: string;\r\n  phone: string | null | undefined;\r\n  userName?: string | null;\r\n  type: string;\r\n  title: string;\r\n  body: string;\r\n  payload?: Record<string, unknown> | null;\r\n  whatsappPref?: boolean | null;\r\n  whatsappOptedInAt?: string | null;\r\n  promotionsPref?: boolean | null;\r\n  notificationId?: string;\r\n}): Promise<{ attempted: boolean; result?: WhatsAppSendResult & { usedTemplate?: boolean }; skipReason?: string }> {\r\n  const payload = normalizeWaPayload(opts.payload);\r\n\r\n  if (!shouldSendWhatsApp({\r\n    type: opts.type,\r\n    whatsappPref: opts.whatsappPref,\r\n    whatsappOptedInAt: opts.whatsappOptedInAt,\r\n    promotionsPref: opts.promotionsPref,\r\n    payload,\r\n  })) {\r\n    return { attempted: false, skipReason: \"not_eligible_or_opted_out\" };\r\n  }\r\n\r\n  const phone = toWaPhone(opts.phone);\r\n  if (!phone) {\r\n    return { attempted: false, skipReason: \"no_phone\" };\r\n  }\r\n\r\n  const mapped = resolveTemplate({\r\n    type: opts.type,\r\n    title: opts.title,\r\n    body: opts.body,\r\n    payload,\r\n    userName: opts.userName || \"there\",\r\n  });\r\n\r\n  const result = await sendWhatsAppTemplateOrText({\r\n    phoneNumber: phone,\r\n    templateName: mapped.templateName,\r\n    bodyParams: mapped.bodyParams,\r\n    fallbackText: mapped.fallbackText,\r\n  });\r\n\r\n  await logWhatsAppMessage({\r\n    direction: \"outbound\",\r\n    phone,\r\n    message: mapped.fallbackText.slice(0, 500),\r\n    meta_message_id: result.metaMessageId || null,\r\n    status: result.success ? \"sent\" : \"failed\",\r\n    error_code: result.success ? null : result.code,\r\n    error_message: result.error || null,\r\n    template_name: result.usedTemplate ? mapped.templateName : null,\r\n    meta_payload: {\r\n      ...(typeof result.meta === \"object\" && result.meta ? result.meta : {}),\r\n      queue_notification_id: opts.notificationId || null,\r\n      used_template: !!result.usedTemplate,\r\n      user_id: opts.userId,\r\n      mapped_template: mapped.templateName,\r\n    },\r\n  });\r\n\r\n  return { attempted: true, result };\r\n}\r\n"},{"name":"functions/_shared/whatsapp.ts","content":"/**\r\n * Shared WhatsApp Cloud API client for Sociva Edge Functions.\r\n * Credentials: admin_settings first, then Deno.env secrets.\r\n */\r\nimport { createAdminClient, getCredential } from \"./credentials.ts\";\r\n\r\nexport const WHATSAPP_GRAPH_VERSION = \"v23.0\";\r\n\r\nexport type WhatsAppSendResult = {\r\n  success: boolean;\r\n  code:\r\n    | \"ok\"\r\n    | \"missing_credentials\"\r\n    | \"invalid_phone\"\r\n    | \"unauthorized\"\r\n    | \"token_expired\"\r\n    | \"rate_limited\"\r\n    | \"meta_error\"\r\n    | \"unexpected\";\r\n  httpStatus?: number;\r\n  metaMessageId?: string;\r\n  meta?: unknown;\r\n  error?: string;\r\n  elapsedMs: number;\r\n};\r\n\r\nexport function normalizeWhatsAppPhone(raw: string): string | null {\r\n  const digits = String(raw || \"\").replace(/\\D/g, \"\");\r\n  if (digits.length < 10 || digits.length > 15) return null;\r\n  return digits;\r\n}\r\n\r\nexport async function loadWhatsAppCredentials() {\r\n  const admin = createAdminClient();\r\n  const [accessToken, phoneNumberId, verifyToken, businessAccountId] = await Promise.all([\r\n    getCredential(admin, \"whatsapp_access_token\", \"WHATSAPP_ACCESS_TOKEN\"),\r\n    getCredential(admin, \"whatsapp_phone_number_id\", \"WHATSAPP_PHONE_NUMBER_ID\"),\r\n    getCredential(admin, \"whatsapp_verify_token\", \"WHATSAPP_VERIFY_TOKEN\"),\r\n    getCredential(admin, \"whatsapp_business_account_id\", \"WHATSAPP_BUSINESS_ACCOUNT_ID\"),\r\n  ]);\r\n  return {\r\n    admin,\r\n    accessToken: accessToken || \"\",\r\n    phoneNumberId: phoneNumberId || \"\",\r\n    verifyToken: verifyToken || \"\",\r\n    businessAccountId: businessAccountId || \"\",\r\n  };\r\n}\r\n\r\nfunction classifyMetaError(httpStatus: number, body: any): WhatsAppSendResult[\"code\"] {\r\n  const errMsg = String(body?.error?.message || body?.error?.error_user_msg || \"\").toLowerCase();\r\n  const errCode = body?.error?.code;\r\n  if (httpStatus === 401 || errCode === 190) return \"token_expired\";\r\n  if (httpStatus === 403) return \"unauthorized\";\r\n  if (httpStatus === 429 || errCode === 4 || errCode === 80007) return \"rate_limited\";\r\n  if (/phone|recipient|invalid.*user|131026|131030/i.test(errMsg) || errCode === 100) {\r\n    return \"invalid_phone\";\r\n  }\r\n  if (httpStatus >= 400) return \"meta_error\";\r\n  return \"unexpected\";\r\n}\r\n\r\nasync function postWhatsAppMessage(payload: Record<string, unknown>): Promise<WhatsAppSendResult> {\r\n  const started = Date.now();\r\n  const { accessToken, phoneNumberId } = await loadWhatsAppCredentials();\r\n  if (!accessToken || !phoneNumberId) {\r\n    return {\r\n      success: false,\r\n      code: \"missing_credentials\",\r\n      error: \"WHATSAPP_ACCESS_TOKEN / WHATSAPP_PHONE_NUMBER_ID not configured\",\r\n      elapsedMs: Date.now() - started,\r\n    };\r\n  }\r\n\r\n  const url = `https://graph.facebook.com/${WHATSAPP_GRAPH_VERSION}/${phoneNumberId}/messages`;\r\n  console.log(\"[whatsapp] outbound\", JSON.stringify(payload).slice(0, 500));\r\n\r\n  try {\r\n    const res = await fetch(url, {\r\n      method: \"POST\",\r\n      headers: {\r\n        Authorization: `Bearer ${accessToken}`,\r\n        \"Content-Type\": \"application/json\",\r\n      },\r\n      body: JSON.stringify(payload),\r\n    });\r\n    const meta = await res.json().catch(() => ({}));\r\n    const elapsedMs = Date.now() - started;\r\n    console.log(\"[whatsapp] http\", res.status, \"elapsedMs\", elapsedMs, \"meta\", JSON.stringify(meta).slice(0, 500));\r\n\r\n    if (!res.ok) {\r\n      const code = classifyMetaError(res.status, meta);\r\n      return {\r\n        success: false,\r\n        code,\r\n        httpStatus: res.status,\r\n        meta,\r\n        error: meta?.error?.message || `Meta HTTP ${res.status}`,\r\n        elapsedMs,\r\n      };\r\n    }\r\n\r\n    return {\r\n      success: true,\r\n      code: \"ok\",\r\n      httpStatus: res.status,\r\n      metaMessageId: meta?.messages?.[0]?.id as string | undefined,\r\n      meta,\r\n      elapsedMs,\r\n    };\r\n  } catch (e) {\r\n    console.error(\"[whatsapp] unexpected\", e);\r\n    return {\r\n      success: false,\r\n      code: \"unexpected\",\r\n      error: String(e),\r\n      elapsedMs: Date.now() - started,\r\n    };\r\n  }\r\n}\r\n\r\nexport async function sendWhatsAppText(opts: {\r\n  phoneNumber: string;\r\n  message: string;\r\n  previewUrl?: boolean;\r\n}): Promise<WhatsAppSendResult> {\r\n  const started = Date.now();\r\n  const phone = normalizeWhatsAppPhone(opts.phoneNumber);\r\n  if (!phone) {\r\n    return {\r\n      success: false,\r\n      code: \"invalid_phone\",\r\n      error: \"Phone must be E.164 digits without +, e.g. 9198XXXXXXXX\",\r\n      elapsedMs: Date.now() - started,\r\n    };\r\n  }\r\n\r\n  return postWhatsAppMessage({\r\n    messaging_product: \"whatsapp\",\r\n    recipient_type: \"individual\",\r\n    to: phone,\r\n    type: \"text\",\r\n    text: {\r\n      preview_url: !!opts.previewUrl,\r\n      body: opts.message,\r\n    },\r\n  });\r\n}\r\n\r\nexport type WhatsAppTemplateComponent = {\r\n  type: \"header\" | \"body\" | \"button\";\r\n  parameters?: Array<{ type: \"text\" | \"currency\" | \"date_time\" | \"image\" | \"document\" | \"video\"; text?: string }>;\r\n  sub_type?: string;\r\n  index?: string;\r\n};\r\n\r\n/** Send an approved Meta message template (required outside the 24h customer service window). */\r\nexport async function sendWhatsAppTemplate(opts: {\r\n  phoneNumber: string;\r\n  templateName: string;\r\n  languageCode?: string;\r\n  components?: WhatsAppTemplateComponent[];\r\n}): Promise<WhatsAppSendResult> {\r\n  const started = Date.now();\r\n  const phone = normalizeWhatsAppPhone(opts.phoneNumber);\r\n  if (!phone) {\r\n    return {\r\n      success: false,\r\n      code: \"invalid_phone\",\r\n      error: \"Phone must be E.164 digits without +, e.g. 9198XXXXXXXX\",\r\n      elapsedMs: Date.now() - started,\r\n    };\r\n  }\r\n  if (!opts.templateName?.trim()) {\r\n    return {\r\n      success: false,\r\n      code: \"meta_error\",\r\n      error: \"templateName is required\",\r\n      elapsedMs: Date.now() - started,\r\n    };\r\n  }\r\n\r\n  const template: Record<string, unknown> = {\r\n    name: opts.templateName.trim(),\r\n    language: { code: opts.languageCode || \"en\" },\r\n  };\r\n  if (opts.components?.length) {\r\n    template.components = opts.components;\r\n  }\r\n\r\n  return postWhatsAppMessage({\r\n    messaging_product: \"whatsapp\",\r\n    recipient_type: \"individual\",\r\n    to: phone,\r\n    type: \"template\",\r\n    template,\r\n  });\r\n}\r\n\r\n/** Prefer Meta template; fall back to free-form text when template is unavailable/unapproved. */\r\nexport async function sendWhatsAppTemplateOrText(opts: {\r\n  phoneNumber: string;\r\n  templateName: string;\r\n  languageCode?: string;\r\n  bodyParams?: string[];\r\n  fallbackText: string;\r\n}): Promise<WhatsAppSendResult & { usedTemplate: boolean }> {\r\n  const components: WhatsAppTemplateComponent[] | undefined = opts.bodyParams?.length\r\n    ? [{\r\n      type: \"body\",\r\n      parameters: opts.bodyParams.map((text) => ({ type: \"text\" as const, text: String(text || \"—\").slice(0, 600) })),\r\n    }]\r\n    : undefined;\r\n\r\n  const tpl = await sendWhatsAppTemplate({\r\n    phoneNumber: opts.phoneNumber,\r\n    templateName: opts.templateName,\r\n    languageCode: opts.languageCode,\r\n    components,\r\n  });\r\n  if (tpl.success) return { ...tpl, usedTemplate: true };\r\n\r\n  // Pending/rejected template or outside eligibility → try session free-form (works inside 24h CSW)\r\n  const text = await sendWhatsAppText({\r\n    phoneNumber: opts.phoneNumber,\r\n    message: opts.fallbackText,\r\n  });\r\n  return { ...text, usedTemplate: false };\r\n}\r\n\r\nexport async function logWhatsAppMessage(row: {\r\n  direction: \"outbound\" | \"inbound\";\r\n  phone: string;\r\n  message?: string | null;\r\n  meta_message_id?: string | null;\r\n  status: string;\r\n  error_code?: string | null;\r\n  error_message?: string | null;\r\n  template_name?: string | null;\r\n  meta_payload?: unknown;\r\n  created_by?: string | null;\r\n}) {\r\n  const admin = createAdminClient();\r\n  const { error } = await admin.from(\"whatsapp_messages\").insert({\r\n    direction: row.direction,\r\n    phone: row.phone,\r\n    message: row.message ?? null,\r\n    meta_message_id: row.meta_message_id ?? null,\r\n    status: row.status,\r\n    error_code: row.error_code ?? null,\r\n    error_message: row.error_message ?? null,\r\n    template_name: row.template_name ?? null,\r\n    meta_payload: row.meta_payload ?? null,\r\n    created_by: row.created_by ?? null,\r\n  });\r\n  if (error) console.error(\"[whatsapp] log insert failed\", error);\r\n}\r\n\r\n/** High-level templates — prefer approved Meta templates, fall back to free-form. */\r\nexport async function sendOTP(phoneNumber: string, otp: string) {\r\n  const message = `Your Sociva verification code is ${otp}. Do not share this code.`;\r\n  // Auth templates require Meta authentication category; until approved, session text only.\r\n  return sendWhatsAppText({ phoneNumber, message });\r\n}\r\n\r\nexport async function sendBookingConfirmation(opts: {\r\n  phoneNumber: string;\r\n  customerName: string;\r\n  bookingId: string;\r\n  providerName: string;\r\n  serviceDate: string;\r\n  serviceTime: string;\r\n}) {\r\n  const fallback =\r\n    `Hi ${opts.customerName}, your booking with ${opts.providerName} is confirmed.\\n` +\r\n    `Booking: ${opts.bookingId}\\n` +\r\n    `When: ${opts.serviceDate} at ${opts.serviceTime}\\n` +\r\n    `— Sociva`;\r\n  return sendWhatsAppTemplateOrText({\r\n    phoneNumber: opts.phoneNumber,\r\n    templateName: \"sociva_booking_confirmed\",\r\n    bodyParams: [\r\n      opts.customerName || \"there\",\r\n      opts.providerName || \"your provider\",\r\n      opts.bookingId || \"—\",\r\n      opts.serviceDate || \"—\",\r\n      opts.serviceTime || \"—\",\r\n    ],\r\n    fallbackText: fallback,\r\n  });\r\n}\r\n\r\nexport async function sendBookingCancelled(opts: {\r\n  phoneNumber: string;\r\n  customerName: string;\r\n  bookingId: string;\r\n  providerName: string;\r\n  reason?: string;\r\n}) {\r\n  const reason = opts.reason || \"No additional details.\";\r\n  const fallback =\r\n    `Hi ${opts.customerName}, your booking ${opts.bookingId} with ${opts.providerName} was cancelled.` +\r\n    `\\nReason: ${reason}\\n— Sociva`;\r\n  return sendWhatsAppTemplateOrText({\r\n    phoneNumber: opts.phoneNumber,\r\n    templateName: \"sociva_booking_cancelled\",\r\n    bodyParams: [\r\n      opts.customerName || \"there\",\r\n      opts.bookingId || \"—\",\r\n      opts.providerName || \"your provider\",\r\n      reason,\r\n    ],\r\n    fallbackText: fallback,\r\n  });\r\n}\r\n\r\nexport async function sendBookingReminder(opts: {\r\n  phoneNumber: string;\r\n  customerName: string;\r\n  bookingId: string;\r\n  providerName: string;\r\n  serviceDate: string;\r\n  serviceTime: string;\r\n}) {\r\n  const fallback =\r\n    `Reminder: Hi ${opts.customerName}, you have a booking with ${opts.providerName} on ` +\r\n    `${opts.serviceDate} at ${opts.serviceTime} (ref ${opts.bookingId}).\\n— Sociva`;\r\n  return sendWhatsAppTemplateOrText({\r\n    phoneNumber: opts.phoneNumber,\r\n    templateName: \"sociva_booking_reminder\",\r\n    bodyParams: [\r\n      opts.customerName || \"there\",\r\n      opts.providerName || \"your provider\",\r\n      opts.serviceDate || \"—\",\r\n      opts.serviceTime || \"—\",\r\n      opts.bookingId || \"—\",\r\n    ],\r\n    fallbackText: fallback,\r\n  });\r\n}\r\n"},{"name":"functions/_shared/rate-limiter.ts","content":"import { createClient } from \"https://esm.sh/@supabase/supabase-js@2.93.3\";\n\n// Module-level shared client — created once per isolate lifetime\nlet _sharedClient: any = null;\nfunction getSharedClient() {\n  if (!_sharedClient) {\n    _sharedClient = createClient(\n      Deno.env.get(\"SUPABASE_URL\")!,\n      Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\")!\n    );\n  }\n  return _sharedClient;\n}\n\n/**\n * Shared rate limiter for edge functions.\n * Uses atomic upsert to prevent race conditions under concurrency.\n * Reuses a module-level Supabase client to avoid cold-start overhead.\n */\nexport async function checkRateLimit(\n  key: string,\n  maxRequests: number,\n  windowSeconds: number\n): Promise<{ allowed: boolean; remaining: number }> {\n  try {\n    const supabase = getSharedClient();\n    const now = new Date();\n    const windowStart = new Date(now.getTime() - windowSeconds * 1000);\n\n    const { data: existing } = await supabase\n      .from(\"rate_limits\")\n      .select(\"*\")\n      .eq(\"key\", key)\n      .single();\n\n    if (existing) {\n      const existingWindowStart = new Date(existing.window_start);\n\n      if (existingWindowStart < windowStart) {\n        const { error } = await supabase\n          .from(\"rate_limits\")\n          .update({ count: 1, window_start: now.toISOString() })\n          .eq(\"key\", key)\n          .eq(\"window_start\", existing.window_start);\n\n        if (error) {\n          return checkRateLimitRetry(supabase, key, maxRequests, windowSeconds);\n        }\n        return { allowed: true, remaining: maxRequests - 1 };\n      }\n\n      if (existing.count >= maxRequests) {\n        return { allowed: false, remaining: 0 };\n      }\n\n      const { data: updated, error } = await supabase\n        .from(\"rate_limits\")\n        .update({ count: existing.count + 1 })\n        .eq(\"key\", key)\n        .eq(\"count\", existing.count)\n        .select(\"count\")\n        .single();\n\n      if (error || !updated) {\n        return checkRateLimitRetry(supabase, key, maxRequests, windowSeconds);\n      }\n\n      return { allowed: true, remaining: maxRequests - updated.count };\n    }\n\n    await supabase\n      .from(\"rate_limits\")\n      .upsert(\n        { key, count: 1, window_start: now.toISOString() },\n        { onConflict: \"key\" }\n      );\n\n    return { allowed: true, remaining: maxRequests - 1 };\n  } catch (error) {\n    console.error(\"Rate limiter error (allowing request):\", error);\n    return { allowed: true, remaining: maxRequests };\n  }\n}\n\nasync function checkRateLimitRetry(\n  supabase: any,\n  key: string,\n  maxRequests: number,\n  _windowSeconds: number\n): Promise<{ allowed: boolean; remaining: number }> {\n  const { data } = await supabase\n    .from(\"rate_limits\")\n    .select(\"count\")\n    .eq(\"key\", key)\n    .single();\n\n  if (!data) return { allowed: true, remaining: maxRequests - 1 };\n\n  if (data.count >= maxRequests) {\n    return { allowed: false, remaining: 0 };\n  }\n\n  const { data: updated, error } = await supabase\n    .from(\"rate_limits\")\n    .update({ count: data.count + 1 })\n    .eq(\"key\", key)\n    .eq(\"count\", data.count)\n    .select(\"count\")\n    .single();\n\n  if (error || !updated) {\n    const { data: final } = await supabase.from(\"rate_limits\").select(\"count\").eq(\"key\", key).single();\n    if (!final || final.count >= maxRequests) return { allowed: false, remaining: 0 };\n    return { allowed: true, remaining: maxRequests - final.count };\n  }\n\n  return { allowed: true, remaining: maxRequests - updated.count };\n}\n\nexport function rateLimitResponse(corsHeaders: Record<string, string>) {\n  return new Response(\n    JSON.stringify({ error: \"Too many requests. Please try again later.\" }),\n    {\n      status: 429,\n      headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\n    }\n  );\n}\n"},{"name":"functions/_shared/notification-ops.ts","content":"/**\n * Shared notification helpers for edge functions (quiet hours, rate limits, DLQ).\n */\n\nexport function isWithinQuietHours(opts: {\n  enabled?: boolean | null;\n  startHour?: number | null;\n  endHour?: number | null;\n  timezone?: string | null;\n  now?: Date;\n}): boolean {\n  if (!opts.enabled) return false;\n  const start = Number.isFinite(opts.startHour as number) ? Number(opts.startHour) : 22;\n  const end = Number.isFinite(opts.endHour as number) ? Number(opts.endHour) : 7;\n  const tz = opts.timezone || \"Asia/Kolkata\";\n  const now = opts.now || new Date();\n\n  let hour: number;\n  try {\n    const parts = new Intl.DateTimeFormat(\"en-US\", {\n      timeZone: tz,\n      hour: \"numeric\",\n      hour12: false,\n    }).formatToParts(now);\n    hour = parseInt(parts.find((p) => p.type === \"hour\")?.value || \"0\", 10);\n    if (hour === 24) hour = 0;\n  } catch {\n    hour = now.getUTCHours();\n  }\n\n  if (start === end) return true; // full-day quiet if misconfigured equal\n  if (start < end) return hour >= start && hour < end;\n  // wraps midnight e.g. 22–7\n  return hour >= start || hour < end;\n}\n\nexport function pnqLog(event: string, fields: Record<string, unknown> = {}): void {\n  console.log(JSON.stringify({ event, ts: new Date().toISOString(), ...fields }));\n}\n\nexport async function moveToDeadLetter(\n  supabase: { from: (t: string) => any },\n  item: {\n    id: string;\n    user_id?: string;\n    type?: string;\n    title?: string;\n    body?: string;\n    reference_path?: string | null;\n    payload?: Record<string, unknown> | null;\n    retry_count?: number;\n    last_error?: string | null;\n    push_skip_reason?: string | null;\n  },\n): Promise<void> {\n  try {\n    await supabase.from(\"notification_dead_letter\").insert({\n      queue_item_id: item.id,\n      user_id: item.user_id ?? null,\n      type: item.type ?? null,\n      title: item.title ?? null,\n      body: item.body ?? null,\n      reference_path: item.reference_path ?? null,\n      payload: item.payload ?? {},\n      retry_count: item.retry_count ?? null,\n      last_error: item.last_error ?? null,\n      push_skip_reason: item.push_skip_reason ?? null,\n    });\n    pnqLog(\"dlq_insert\", { queue_item_id: item.id, type: item.type, last_error: item.last_error });\n  } catch (e) {\n    console.warn(\"[PNQ] DLQ insert failed:\", e);\n  }\n}\n\nexport async function updateTokenHealth(\n  supabase: { from: (t: string) => any },\n  tokenRecord: {\n    id: string;\n    health_score?: number | null;\n    consecutive_failures?: number | null;\n    invalid_count?: number | null;\n  },\n  result: { success: boolean; error?: string },\n): Promise<void> {\n  try {\n    if (result.success) {\n      await supabase.from(\"device_tokens\").update({\n        health_score: 100,\n        consecutive_failures: 0,\n        last_success_at: new Date().toISOString(),\n        last_error_code: null,\n        invalid: false,\n      }).eq(\"id\", tokenRecord.id);\n      return;\n    }\n\n    const failures = (tokenRecord.consecutive_failures || 0) + 1;\n    const health = Math.max(0, 100 - failures * 20);\n    const isInvalid = result.error === \"INVALID_TOKEN\";\n    const shouldPrune = isInvalid || failures >= 5 || health <= 10;\n\n    await supabase.from(\"device_tokens\").update({\n      health_score: health,\n      consecutive_failures: failures,\n      last_error_code: result.error || \"unknown\",\n      invalid: shouldPrune,\n      invalid_count: (tokenRecord.invalid_count || 0) + (isInvalid || shouldPrune ? 1 : 0),\n    }).eq(\"id\", tokenRecord.id);\n\n    pnqLog(\"token_health_update\", {\n      token_id: tokenRecord.id,\n      health_score: health,\n      consecutive_failures: failures,\n      invalid: shouldPrune,\n      error: result.error || null,\n    });\n  } catch (e) {\n    console.warn(\"[PNQ] token health update failed:\", e);\n  }\n}\n"}]};